const TIER_STYLE = {
  'Gold Standard': { color: '#F4CE5B', bg: 'rgba(244,206,91,0.14)', border: '#F4CE5B' },
  'Elite Gold':    { color: '#E0B24A', bg: 'rgba(224,178,74,0.12)', border: '#E0B24A' },
  'Strong Gold':   { color: '#C99A45', bg: 'rgba(201,154,69,0.10)', border: '#C99A45' },
  'Silver':        { color: '#B9C0C6', bg: 'rgba(185,192,198,0.10)', border: '#B9C0C6' },
  'Bronze':        { color: '#B9773F', bg: 'rgba(185,119,63,0.10)', border: '#B9773F' },
};

const MEDALS = ['\u{1F947}', '\u{1F948}', '\u{1F949}'];

function Bar({ label, value }) {
  return (
    <div className="gold-bar-row">
      <span className="gold-bar-label">{label}</span>
      <div className="gold-bar-track">
        <div className="gold-bar-fill" style={{ width: value + '%' }} />
      </div>
      <span className="gold-bar-value">{value.toFixed(0)}</span>
    </div>
  );
}

function PodiumCard({ player, rank, statLine }) {
  const tier = TIER_STYLE[player.Tier];
  return (
    <div className={"podium-card podium-" + rank}>
      <div className="podium-medal">{MEDALS[rank - 1]}</div>
      <div className="podium-rank">RANK {rank}</div>
      <div className="podium-name">{player.Name}</div>
      <div className="podium-years">{player.FirstYear}\u2013{player.LastYear} \u00b7 {player.Seasons} seasons</div>
      <div className="podium-score">{player.GOLD.toFixed(1)}</div>
      <div className="podium-tier" style={{ color: tier.color, borderColor: tier.border, background: tier.bg }}>{player.Tier}</div>
      <div className="podium-stat">{statLine(player)}</div>
    </div>
  );
}

function PlayerRow({ player, expanded, onToggle, statLine }) {
  const tier = TIER_STYLE[player.Tier];
  return (
    <div className="ledger-row-wrap">
      <button className="ledger-row" style={{ borderLeftColor: tier.border }} onClick={onToggle}>
        <span className="ledger-rank">{player.Rank}</span>
        <span className="ledger-name">
          {player.Name}
          <span className="ledger-years">{player.FirstYear}\u2013{player.LastYear}</span>
        </span>
        <span className="ledger-stat">{statLine(player)}</span>
        <span className="ledger-tier" style={{ color: tier.color, borderColor: tier.border, background: tier.bg }}>{player.Tier}</span>
        <span className="ledger-score">{player.GOLD.toFixed(1)}</span>
        <span className={"ledger-caret" + (expanded ? ' open' : '')}>\u2304</span>
      </button>
      {expanded && (
        <div className="ledger-detail">
          <Bar label="Contribution (G)" value={player.G} />
          <Bar label="Production (O)" value={player.O} />
          <Bar label="Longevity (L)" value={player.L} />
          <Bar label="Dominance (D)" value={player.D} />
        </div>
      )}
    </div>
  );
}

export default function GiantsGoldStandard() {
  const [mode, setMode] = useState('hitters');
  const [query, setQuery] = useState('');
  const [openName, setOpenName] = useState(null);
  const [showAll, setShowAll] = useState(false);

  const data = mode === 'hitters' ? HITTERS : PITCHERS;

  const statLine = mode === 'hitters'
    ? (p) => p.HR + ' HR \u00b7 ' + p.RBI + ' RBI \u00b7 ' + p.OPS_plus.toFixed(0) + ' OPS+'
    : (p) => p.Wins + '-' + p.Losses + ' \u00b7 ' + p.SO + ' K \u00b7 ' + p.ERA_plus.toFixed(0) + ' ERA+';

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const base = q ? data.filter(p => p.Name.toLowerCase().includes(q)) : data;
    return base;
  }, [data, query]);

  const visible = showAll || query.trim() ? filtered : filtered.slice(0, 25);
  const podium = !query.trim() ? data.slice(0, 3) : [];

  return (
    <div className="gs-root">
      <style>{`
        .gs-root {
          background: radial-gradient(ellipse at top, #201d17 0%, #131210 55%, #0c0b0a 100%);
          color: #EDE7DA;
          font-family: Georgia, 'Iowan Old Style', 'Times New Roman', serif;
          padding: 28px 18px 48px;
          min-height: 100%;
          box-sizing: border-box;
        }
        .gs-root * { box-sizing: border-box; }
        .gs-header { max-width: 980px; margin: 0 auto 28px; text-align: center; }
        .gs-eyebrow {
          font-family: Arial, Helvetica, sans-serif;
          font-size: 11px; letter-spacing: 3px; text-transform: uppercase;
          color: #FD5A1E; font-weight: 700; margin-bottom: 10px;
        }
        .gs-title {
          font-family: 'Arial Narrow', Arial, sans-serif;
          font-weight: 800;
          font-size: clamp(34px, 7vw, 58px);
          letter-spacing: 2px;
          text-transform: uppercase;
          margin: 0;
          background: linear-gradient(180deg, #F6D875 0%, #C99A45 55%, #9c7830 100%);
          -webkit-background-clip: text;
          background-clip: text;
          color: transparent;
          line-height: 1.02;
        }
        .gs-subtitle {
          font-family: Arial, Helvetica, sans-serif;
          font-size: 13.5px; color: #B9B2A0; max-width: 620px; margin: 14px auto 0;
          line-height: 1.6;
        }
        .gs-formula {
          font-family: 'Courier New', monospace;
          font-size: 12.5px; color: #E0B24A; margin-top: 12px;
          letter-spacing: 0.3px;
        }
        .gs-controls {
          max-width: 980px; margin: 26px auto 22px;
          display: flex; gap: 12px; align-items: center; justify-content: center;
          flex-wrap: wrap;
        }
        .gs-toggle { display: inline-flex; border: 1px solid rgba(255,255,255,0.15); border-radius: 999px; padding: 3px; background: rgba(255,255,255,0.03); }
        .gs-toggle button {
          font-family: Arial, sans-serif; font-weight: 700; font-size: 12.5px; letter-spacing: 1px;
          text-transform: uppercase; padding: 9px 20px; border-radius: 999px; border: none;
          background: transparent; color: #B9B2A0; cursor: pointer; transition: all 0.15s ease;
        }
        .gs-toggle button.active { background: #FD5A1E; color: #141311; }
        .gs-search {
          font-family: Arial, sans-serif; font-size: 13px;
          background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.15);
          color: #EDE7DA; padding: 10px 16px; border-radius: 999px; width: 220px;
          outline: none;
        }
        .gs-search::placeholder { color: #7a7365; }
        .gs-search:focus { border-color: #C99A45; }

        .podium-wrap {
          max-width: 900px; margin: 0 auto 34px; display: grid;
          grid-template-columns: repeat(3, 1fr); gap: 14px; align-items: end;
        }
        .podium-card {
          background: linear-gradient(180deg, #EFE7D4 0%, #E4DAC1 100%);
          color: #2b2620; border-radius: 10px; padding: 20px 14px 18px;
          text-align: center; position: relative;
          box-shadow: 0 10px 30px rgba(0,0,0,0.35);
          border: 1px solid rgba(0,0,0,0.08);
        }
        .podium-1 { transform: translateY(-14px); padding-top: 26px; }
        .podium-medal { font-size: 30px; line-height: 1; margin-bottom: 4px; }
        .podium-rank { font-family: Arial, sans-serif; font-size: 10px; letter-spacing: 2px; color: #8a7a4f; font-weight: 700; }
        .podium-name { font-family: 'Arial Narrow', Arial, sans-serif; font-weight: 800; font-size: 17px; margin-top: 6px; text-transform: uppercase; letter-spacing: 0.3px; }
        .podium-years { font-family: Arial, sans-serif; font-size: 10.5px; color: #6b6252; margin-top: 3px; }
        .podium-score { font-family: 'Arial Narrow', Arial, sans-serif; font-weight: 800; font-size: 34px; color: #9c6f1e; margin-top: 8px; }
        .podium-tier {
          display: inline-block; font-family: Arial, sans-serif; font-size: 10px; font-weight: 700;
          letter-spacing: 0.6px; padding: 3px 10px; border-radius: 999px; border: 1px solid; margin-top: 6px;
        }
        .podium-stat { font-family: Arial, sans-serif; font-size: 11px; color: #55503f; margin-top: 10px; }

        .ledger-wrap { max-width: 900px; margin: 0 auto; background: rgba(239,231,212,0.04); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; overflow: hidden; }
        .ledger-head {
          font-family: Arial, sans-serif; font-size: 10.5px; letter-spacing: 1.2px; text-transform: uppercase;
          color: #8a8272; display: grid; grid-template-columns: 34px 1fr 150px 108px 60px 18px; gap: 10px;
          padding: 10px 16px; border-bottom: 1px solid rgba(255,255,255,0.08);
        }
        .ledger-row-wrap { border-bottom: 1px solid rgba(255,255,255,0.06); }
        .ledger-row {
          all: unset; cursor: pointer; width: 100%; display: grid;
          grid-template-columns: 34px 1fr 150px 108px 60px 18px; gap: 10px; align-items: center;
          padding: 12px 16px; border-left: 3px solid transparent;
        }
        .ledger-row:hover { background: rgba(255,255,255,0.03); }
        .ledger-rank { font-family: 'Arial Narrow', Arial, sans-serif; font-weight: 800; color: #7a7365; font-size: 14px; }
        .ledger-name { font-family: Arial, sans-serif; font-weight: 700; font-size: 14px; color: #EDE7DA; display: flex; flex-direction: column; }
        .ledger-years { font-weight: 400; font-size: 10.5px; color: #8a8272; margin-top: 1px; }
        .ledger-stat { font-family: 'Courier New', monospace; font-size: 11px; color: #B9B2A0; }
        .ledger-tier { font-family: Arial, sans-serif; font-size: 9.5px; font-weight: 700; text-align: center; padding: 3px 6px; border-radius: 999px; border: 1px solid; white-space: nowrap; }
        .ledger-score { font-family: 'Arial Narrow', Arial, sans-serif; font-weight: 800; font-size: 16px; color: #E0B24A; text-align: right; }
        .ledger-caret { color: #7a7365; transition: transform 0.15s ease; justify-self: end; }
        .ledger-caret.open { transform: rotate(180deg); }
        .ledger-detail { padding: 4px 16px 16px 66px; background: rgba(0,0,0,0.15); }

        .gold-bar-row { display: grid; grid-template-columns: 130px 1fr 30px; align-items: center; gap: 10px; padding: 4px 0; }
        .gold-bar-label { font-family: Arial, sans-serif; font-size: 10.5px; color: #8a8272; }
        .gold-bar-track { height: 6px; background: rgba(255,255,255,0.08); border-radius: 999px; overflow: hidden; }
        .gold-bar-fill { height: 100%; background: linear-gradient(90deg, #C99A45, #F4CE5B); border-radius: 999px; }
        .gold-bar-value { font-family: 'Courier New', monospace; font-size: 11px; color: #C99A45; text-align: right; }

        .gs-showmore { display: block; margin: 18px auto 0; font-family: Arial, sans-serif; font-size: 12px; font-weight: 700;
          letter-spacing: 0.8px; text-transform: uppercase; color: #C99A45; background: transparent; border: 1px solid rgba(201,154,69,0.4);
          padding: 10px 22px; border-radius: 999px; cursor: pointer; }
        .gs-showmore:hover { background: rgba(201,154,69,0.1); }

        .gs-footnote { max-width: 700px; margin: 24px auto 0; text-align: center; font-family: Arial, sans-serif; font-size: 11px; color: #726c5d; line-height: 1.7; }

        @media (max-width: 640px) {
          .podium-wrap { grid-template-columns: 1fr; }
          .podium-1 { order: -1; transform: none; }
          .ledger-head, .ledger-row { grid-template-columns: 24px 1fr 60px 18px; }
          .ledger-stat, .ledger-tier { display: none; }
        }
      `}</style>

      <div className="gs-header">
        <div className="gs-eyebrow">San Francisco Giants \u00b7 1958\u20132023</div>
        <h1 className="gs-title">Giants Gold Standard</h1>
        <p className="gs-subtitle">
          GOLD \u2014 Giants Overall Legacy &amp; Dominance. A franchise-only measure of legacy:
          not who was best in all of baseball, but who mattered most to the Giants.
        </p>
        <div className="gs-formula">GOLD = 0.30\u00b7Contribution + 0.30\u00b7Production + 0.20\u00b7Longevity + 0.20\u00b7Dominance</div>
      </div>

      <div className="gs-controls">
        <div className="gs-toggle">
          <button className={mode === 'hitters' ? 'active' : ''} onClick={() => { setMode('hitters'); setOpenName(null); setShowAll(false); }}>Hitters</button>
          <button className={mode === 'pitchers' ? 'active' : ''} onClick={() => { setMode('pitchers'); setOpenName(null); setShowAll(false); }}>Pitchers</button>
        </div>
        <input
          className="gs-search"
          placeholder="Search a player..."
          value={query}
          onChange={(e) => { setQuery(e.target.value); setOpenName(null); }}
        />
      </div>

      {podium.length === 3 && (
        <div className="podium-wrap">
          <PodiumCard player={podium[1]} rank={2} statLine={statLine} />
          <PodiumCard player={podium[0]} rank={1} statLine={statLine} />
          <PodiumCard player={podium[2]} rank={3} statLine={statLine} />
        </div>
      )}

      <div className="ledger-wrap">
        <div className="ledger-head">
          <span>#</span><span>Player</span><span>Line</span><span>Tier</span><span style={{textAlign:'right'}}>GOLD</span><span></span>
        </div>
        {visible.map((p) => (
          <PlayerRow
            key={p.Name + p.FirstYear}
            player={p}
            statLine={statLine}
            expanded={openName === p.Name}
            onToggle={() => setOpenName(openName === p.Name ? null : p.Name)}
          />
        ))}
      </div>

      {!showAll && !query.trim() && filtered.length > 25 && (
        <button className="gs-showmore" onClick={() => setShowAll(true)}>Show all {filtered.length} qualified {mode}</button>
      )}

      <div className="gs-footnote">
        Qualified players only ({mode === 'hitters' ? '500+ career plate appearances' : '150+ career innings pitched'}).
        Rate stats (OPS+, ERA+) are shrunk toward league average for small samples so a hot short stretch can\u2019t outrank a real Giants peak.
        Tiers: Gold Standard 95+, Elite Gold 90\u201394.9, Strong Gold 80\u201389.9, Silver 70\u201379.9, Bronze below 70.
      </div>
    </div>
  );
}
